static ssize_t mcp4725_write_powerdown ( struct iio_dev * indio_dev , uintptr_t private , const struct iio_chan_spec * chan , const char * buf , size_t len ) { struct mcp4725_data * data = iio_priv ( indio_dev ) ; bool state ; int ret ; ret = strtobool ( buf , & state ) ; if ( state ) { ret = mcp4725_suspend ( & data -> client -> dev ) ; } else { ret = mcp4725_resume ( & data -> client -> dev ) ; } if ( ret < 0 ) { return ret ; } return len ; } 